USE nyc_taxi_ldw;
GO

CREATE OR ALTER PROCEDURE silver.usp_silver_trip_data_green_loader
AS 
BEGIN
    DECLARE @sql NVARCHAR(MAX);

    SELECT @sql = STRING_AGG(
            CAST('EXEC silver.usp_silver_trip_data_green ''' 
            + CAST(year AS VARCHAR(4)) + ''','''
            + RIGHT('0' + CAST(month AS VARCHAR(2)), 2) + ''';' AS NVARCHAR(MAX)),
            CHAR(10)
        )
    FROM (
            SELECT DISTINCT
                CAST(year AS VARCHAR(4)) AS year,
                RIGHT('0' + CAST(month AS VARCHAR(2)), 2) AS month
            FROM bronze.vw_trip_data_green_csv
        ) AS x;

    EXEC(@sql);

END
